examples.template:
VStack(alignment: .leading, spacing: theme.spacing.space2) {
    MonarchDeltaIndicator({{items.0.value}}, comparison: {{items.0.comparison}})
    MonarchDeltaIndicator({{items.1.value}}, comparison: {{items.1.comparison}})
    MonarchDeltaIndicator(
        Double({{items.2.current}} - {{items.2.previous}}),
        comparison: {{items.2.comparison}},
        goodDirection: .{{items.2.goodDirection|raw}},
        formatValue: { "\(Int(abs($0))) {{items.2.unit|raw}}" }
    )
    MonarchDeltaIndicator(
        {{items.3.value}},
        comparison: {{items.3.comparison}},
        goodDirection: .{{items.3.goodDirection|raw}},
        formatValue: { $0.formatted(.currency(code: {{items.3.currency}}).locale(Locale(identifier: {{locale}}))) }
    )
}
.environment(\.locale, Locale(identifier: {{locale}}))

examples.code:
VStack(alignment: .leading, spacing: theme.spacing.space2) {
    MonarchDeltaIndicator(0.124, comparison: "vs last month")
    MonarchDeltaIndicator(-0.052, comparison: "vs last month")
    MonarchDeltaIndicator(
        Double(182 - 240),
        comparison: "vs last week",
        goodDirection: .down,
        formatValue: { "\(Int(abs($0))) ms" }
    )
    MonarchDeltaIndicator(
        1250,
        comparison: "in spend",
        goodDirection: .down,
        formatValue: { $0.formatted(.currency(code: "USD").locale(Locale(identifier: "en-US"))) }
    )
}
.environment(\.locale, Locale(identifier: "en-US"))
